/* From Uiverse.io by 1osm - Tags: button */
/* Button 1 */
.__UIV_SCOPE__ .Btn {
  width: 150px;
  height: 50px;
  background-color: transparent;
  color: white;
  font-weight: bold;
  border-width: 2px;
  border-color: #FF5858;
  border-radius: 20px;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .Btn:hover {
  transform: translateY(-10px);
  background-color: #FF5858;
}

.__UIV_SCOPE__ .Btn::after {
  transform: translateY(0);
}
